## Audit table + trigger DDL, generated by sync_audit_table() -- tested OFFLINE.
## The database calls are replaced by fakes that record the SQL, so these tests
## check column pairing, trigger branches and drift handling without Oracle.
## (Needs testthat >= 3.2.0 for local_mocked_bindings.)

make_fake_sqlquery <- function(captured, compile_errors = NULL, trigger_result = character(0)) {
  function(channel, query, ...) {
    if (grepl("CREATE OR REPLACE TRIGGER", query, fixed = TRUE)) {
      captured$trigger <- query
      return(trigger_result)
    }
    if (grepl("nullable", query, fixed = TRUE)) {
      return(data.frame(COLUMN_NAME = character(), stringsAsFactors = FALSE))
    }
    if (grepl("all_errors", query, fixed = TRUE)) {
      if (!is.null(compile_errors)) {
        return(compile_errors)
      }
      return(data.frame(LINE = integer(), POSITION = integer(), TEXT = character(), stringsAsFactors = FALSE))
    }
    stop("unexpected query in fake: ", query)
  }
}

#' Run sync_audit_table() against fakes. `prod_cols` = columns of the production
#' table, `audit_cols` = columns of the existing audit table (character() = none).
run_sync <- function(prod_cols, audit_cols = character(), keys = "ID", rebuild = FALSE,
                     compile_errors = NULL, trigger_result = character(0),
                     env = parent.frame()) {
  captured <- new.env()
  captured$sql <- character()
  testthat::local_mocked_bindings(
    sqlQuery = make_fake_sqlquery(captured, compile_errors, trigger_result),
    .package = "RODBC", .env = env
  )
  with_stubs(
    list(
      get_table_columns = function(channel, schema, table) {
        if (grepl("^AUDIT_", table)) audit_cols else prod_cols
      },
      run_sql = function(channel, sql, what = "SQL statement") {
        captured$sql <- c(captured$sql, sql)
        invisible(TRUE)
      }
    ),
    sync_audit_table("fake", "SCH", "TBL", keys, rebuild = rebuild)
  )
  captured
}

test_that("audit table pairs every non-key column as _CURRENT / _UPDATE", {
  skip_if_not_installed("testthat", "3.2.0")
  cap <- run_sync(c("ID", "LABEL", "ACTIVE"))
  ctas <- paste(cap$sql, collapse = "\n")
  expect_match(ctas, "CREATE TABLE SCH.AUDIT_TBL AS", fixed = TRUE)
  expect_match(ctas, "OPERATION_TYPE", fixed = TRUE)
  expect_match(ctas, "ID, LABEL AS LABEL_CURRENT, LABEL AS LABEL_UPDATE, ACTIVE AS ACTIVE_CURRENT, ACTIVE AS ACTIVE_UPDATE", fixed = TRUE)
  # audit tables are no longer granted to PUBLIC automatically (access is managed via
  # registry `grants` / sync_grants()); this guards against it quietly coming back
  expect_false(any(grepl("TO PUBLIC", cap$sql, fixed = TRUE)))
})

test_that("trigger has INSERT / DELETE / UPDATE branches that use :NEW / :OLD correctly", {
  skip_if_not_installed("testthat", "3.2.0")
  trg <- run_sync(c("ID", "LABEL", "ACTIVE"))$trigger
  expect_match(trg, "CREATE OR REPLACE TRIGGER SCH.AUDIT_TBL", fixed = TRUE)
  expect_match(trg, "AFTER INSERT OR DELETE OR UPDATE ON SCH.TBL", fixed = TRUE)
  expect_match(trg, "FOR EACH ROW", fixed = TRUE)
  
  parts <- strsplit(trg, "ELSIF DELETING THEN", fixed = TRUE)[[1]]
  expect_length(parts, 2)
  ins <- parts[1]
  rest <- strsplit(parts[2], "ELSIF UPDATING THEN", fixed = TRUE)[[1]]
  expect_length(rest, 2)
  del <- rest[1]
  upd <- rest[2]
  
  # INSERT: new values only
  expect_match(ins, ":NEW.ID", fixed = TRUE)
  expect_match(ins, ":NEW.LABEL", fixed = TRUE)
  expect_false(grepl(":OLD.", ins, fixed = TRUE))
  expect_match(ins, "'INSERT'", fixed = TRUE)
  # DELETE: old values only (the key too)
  expect_match(del, ":OLD.ID", fixed = TRUE)
  expect_match(del, ":OLD.LABEL", fixed = TRUE)
  expect_false(grepl(":NEW.", del, fixed = TRUE))
  expect_match(del, "'DELETE'", fixed = TRUE)
  # UPDATE: key from NEW, and each CURRENT column receives OLD while each UPDATE column receives NEW
  expect_match(upd, "'UPDATE'", fixed = TRUE)
  expect_match(upd, "LABEL_CURRENT, LABEL_UPDATE, ACTIVE_CURRENT, ACTIVE_UPDATE", fixed = TRUE)
  expect_match(upd, ":OLD.LABEL, :NEW.LABEL, :OLD.ACTIVE, :NEW.ACTIVE", fixed = TRUE)
})

test_that("a table whose columns are ALL keys (e.g. composition) gets no pair columns", {
  skip_if_not_installed("testthat", "3.2.0")
  cap <- run_sync(c("PID", "CODE"), keys = c("PID", "CODE"))
  all_sql <- paste(c(cap$sql, cap$trigger), collapse = "\n")
  expect_false(grepl("_CURRENT|_UPDATE", all_sql))
  expect_match(all_sql, "PID, CODE", fixed = TRUE)
})

test_that("an existing audit table that matches is left alone (trigger is still refreshed)", {
  skip_if_not_installed("testthat", "3.2.0")
  cols <- c(
    "OPERATION_TYPE", "OPERATION_TIMESTAMP", "USER_NAME", "ID",
    "LABEL_CURRENT", "LABEL_UPDATE"
  )
  cap <- run_sync(c("ID", "LABEL"), audit_cols = cols)
  expect_false(any(grepl("CREATE TABLE", cap$sql, fixed = TRUE)))
  expect_false(any(grepl("RENAME TO", cap$sql, fixed = TRUE)))
  expect_false(is.null(cap$trigger))
})

test_that("column drift stops the run unless rebuild = TRUE, which renames the old audit table", {
  skip_if_not_installed("testthat", "3.2.0")
  stale <- c("OPERATION_TYPE", "OPERATION_TIMESTAMP", "USER_NAME", "ID", "LABEL_CURRENT", "LABEL_UPDATE")
  # production table gained a column (ACTIVE) the audit table doesn't have
  expect_error(run_sync(c("ID", "LABEL", "ACTIVE"), audit_cols = stale), "columns don't match")
  
  cap <- run_sync(c("ID", "LABEL", "ACTIVE"), audit_cols = stale, rebuild = TRUE)
  sql <- paste(cap$sql, collapse = "\n")
  expect_match(sql, "RENAME TO AUDIT_TBL_BAK", fixed = TRUE)
  expect_match(sql, "ACTIVE AS ACTIVE_CURRENT", fixed = TRUE)
})

test_that("bad inputs fail loudly", {
  skip_if_not_installed("testthat", "3.2.0")
  expect_error(run_sync(c("ID", "LABEL"), keys = "NOPE"), "audit key")
  expect_error(run_sync(character()), "Table not found")
})

test_that("trigger compile errors and hard DDL failures are surfaced, not swallowed", {
  skip_if_not_installed("testthat", "3.2.0")
  errs <- data.frame(LINE = 3L, POSITION = 5L, TEXT = "PLS-00201: identifier must be declared", stringsAsFactors = FALSE)
  expect_error(run_sync(c("ID", "LABEL"), compile_errors = errs), "failed to compile")
  expect_error(
    run_sync(c("ID", "LABEL"), trigger_result = "ORA-01031: insufficient privileges"),
    "Creating trigger SCH.AUDIT_TBL failed"
  )
})